// beattie-src/src/data/index.ts
var allTests = [
  emotionalHealth,
  anger,
  fear,
  drama,
  guilt,
  grief
];
function getTestById(id) {
  return allTests.find((t) => t.id === id);
}

// beattie-src/src/lib/scoring.ts
function scoreLikert(values) {
  return values.reduce((sum, v) => sum + (typeof v === "number" ? v : 0), 0);
}
function scoreMcq(items, answers) {
  return items.reduce((sum, item, i) => {
    const a = answers[i];
    if (a === null || a === void 0) return sum;
    if (a === "NA") {
      return sum + (item.naScore ?? 0);
    }
    const pts = item.scores[a];
    return sum + (typeof pts === "number" ? pts : 0);
  }, 0);
}
function scoreTf(items, answers) {
  return items.reduce((sum, item, i) => {
    const a = answers[i];
    if (a === null || a === void 0) return sum;
    if (a === "NA") return sum + 10;
    if (item.expected === "either") return sum + 10;
    if (a === item.expected) return sum + 10;
    return sum;
  }, 0);
}
function findBand(bands, total) {
  return bands.find((b) => total >= b.min && total <= b.max);
}
function computeTotal(test, sections) {
  const total = sections.assessment + sections.mcq + sections.tf;
  return { total, band: findBand(test.bands, total) };
}

